#define GLYPH_COUNT (sizeof(g_font)/sizeof(g_font[0]))
#define NOTDEF_ADV 6

int switch_font_w(void) { return 8; }  /* legacy cell hint (no fixed cell anymore) */
int switch_font_h(void) { return 16; }

static const FontGlyph* glyph_for(uint32_t cp) {
    /* binary search: table sorted by codepoint */
    size_t lo = 0, hi = GLYPH_COUNT;
    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        if (g_font[mid].cp == cp) return &g_font[mid];
        if (g_font[mid].cp < cp) lo = mid + 1; else hi = mid;
    }
    return NULL; /* .notdef -> blank cell, NOTDEF_ADV advance */
}

/* Decode one UTF-8 codepoint; advances *pp. Returns 0xFFFD on garbage. */
static uint32_t utf8_next(const char** pp) {
    const unsigned char* s = (const unsigned char*)*pp;
    unsigned char c = *s;
    if (c < 0x80) { (*pp)++; return c; }
    uint32_t cp = 0; int extra = 0;
    if ((c & 0xE0) == 0xC0) { cp = c & 0x1F; extra = 1; }
    else if ((c & 0xF0) == 0xE0) { cp = c & 0x0F; extra = 2; }
    else if ((c & 0xF8) == 0xF0) { cp = c & 0x07; extra = 3; }
    else { (*pp)++; return 0xFFFD; }
    s++;
    for (int i = 0; i < extra; i++, s++) {
        if ((*s & 0xC0) != 0x80) { (*pp)++; return 0xFFFD; }
        cp = (cp << 6) | (*s & 0x3F);
    }
    *pp = (const char*)(s);
    return cp;
}

int switch_font_draw_text(uint32_t* dst, int dst_w, int dst_h,
                          int x, int y, const char* utf8,
                          uint32_t fg, uint32_t bg, int scale) {
    if (!dst || !utf8 || scale < 1) return x;
    if (WILDGUARD_SKIP(dst, "font:dst")) return x;   /* [WILDGUARD] v36.50 */
    if (WILDGUARD_SKIP(utf8, "font:text")) return x; /* мусорная строка = пустой рендер */
    const char* p = utf8;
    int cx = x;
    while (*p) {
        uint32_t cp = utf8_next(&p);
        const FontGlyph* g = glyph_for(cp);
        int bw = g ? g->w : 0;
        for (int gy = 0; gy < 16; gy++) {
            uint16_t bits = g ? g->rows[gy] : 0;
            for (int gx = 0; gx < bw; gx++) {
                int on = (bits >> (15 - gx)) & 1;
                if (!on) {
                    if (bg == 0x00000000u) continue; /* transparent bg */
                    /* bg pixel: fall through to the plot below */
                }
                uint32_t color = on ? fg : bg;
                for (int sy = 0; sy < scale; sy++) {
                    for (int sx = 0; sx < scale; sx++) {
                        int px = cx + gx * scale + sx;
                        int py = y + gy * scale + sy;
                        if (px >= 0 && px < dst_w && py >= 0 && py < dst_h)
                            dst[py * dst_w + px] = color;
                    }
                }
            }
        }
        cx += (g ? g->adv : NOTDEF_ADV) * scale;
        if (cx >= dst_w) break;
    }
    return cx;
}

int switch_font_text_width(const char* utf8, int scale) {
    if (!utf8) return 0;
    if (WILDGUARD_SKIP(utf8, "font:width")) return 0; /* [WILDGUARD] v36.50 */
    int w = 0;
    const char* p = utf8;
    while (*p) {
        uint32_t cp = utf8_next(&p);
        const FontGlyph* g = glyph_for(cp);
        w += (g ? g->adv : NOTDEF_ADV) * scale;
    }
    return w;
}
